"""Offline report; all data embedded, no CDN/network dependencies."""
import html
import json

def render(run,spec,tasks,stats,ports,summary):
    data=json.dumps(dict(spec=spec,tasks=tasks,stats=stats,ports=ports,summary=summary),ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    template=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>SUE Scale-Up Ethernet 仿真平台 v2 实验报告</title><style>
body{font:16px/1.65 system-ui,sans-serif;max-width:1200px;margin:32px auto;padding:0 20px;color:#183044;background:#f5f8fa}h1,h2{line-height:1.3}.card{background:white;padding:20px;border-radius:12px;margin:18px 0;border:1px solid #dce5eb}.metrics{display:flex;gap:20px;flex-wrap:wrap}.metric{min-width:180px}strong{color:#126b83}label{margin-right:18px}input,select,button{font:inherit;padding:5px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;padding:7px;border-bottom:1px solid #dde4eb}svg{width:100%;background:#fafcfd}pre{white-space:pre-wrap;font-size:13px}.scroll{overflow:auto;max-height:500px}.bad{color:#b3261e}
</style><h1>SUE Scale-Up Ethernet 仿真平台 v2 通信仿真报告</h1><p id="name"></p>
<div class="card"><div id="metrics" class="metrics"></div><p id="goal"></p><p id="prediction"></p><p>建模边界：SUE AFH + LLR / 配置流控。计算仅为固定等待，未模拟 GPU 计算资源排队、HBM 或服务调度。本报告的时间不是实际模型 TTFT / TPOT。</p><p id="semantics"></p></div>
<div class="card"><h2>任务时间线</h2><p>横轴是仿真开始后的时间（µs）；每条横线从任务开始到目的端收齐数据。它包含应用注入、排队和网络传输。计算等待单独画为虚线，范围为依赖可见到等待结束。灰点表示最后一个分片入队时间，不代表线上发送完成。未完成任务显示红色。为便于阅读，每页最多 80 条。</p>
<label>源端点 <select id="source"><option value="all">全部</option></select></label><label>阶段 <select id="label"><option value="all">全部</option></select></label><button id="prev">上一页</button> <button id="next">下一页</button> <span id="page"></span><svg id="timeline" role="img" aria-label="任务时间线"></svg></div>
<div class="card"><h2>各端点逻辑通信量</h2><p>蓝色是任务定义的发送有效载荷，绿色是实际接收的有效载荷，单位 KiB。两者按端点分组而非按流配对；收发不对称可以来自工作负载本身。此图不包含 AFH/LLR 头、控制消息或重传开销，因此不能当作链路利用率。</p><svg id="bytes" role="img" aria-label="端点通信量"></svg></div>
<div class="card"><h2>协议与队列证据</h2><p>replay_frames 是所有重传轮次的帧数；replay_sessions 是完成的 REPLAY 状态会话数。credit_exhausted 是信用门检查失败次数，会受调度频率影响，不能换算成阻塞时间或丢包数。discard 是 LLR 丢弃数。统计覆盖整个配置的仿真截止时间。</p><div class="scroll"><table><thead><tr><th>节点:端口</th><th>重传帧</th><th>重传会话</th><th>NACK 发出</th><th>信用检查失败</th><th>LLR 丢弃</th></tr></thead><tbody id="ports"></tbody></table></div></div>
<div class="card"><h2>任务明细</h2><p>ready：依赖通知全部到达；start：固定等待结束、开始注入。end：目的端收齐。网络任务持续时间=end−start；总窗口从最早 start 到最后 end，包含中间的依赖通知和计算等待。−1 表示尚未发生。</p><div class="scroll"><table><thead><tr><th>任务</th><th>阶段</th><th>源→目的</th><th>字节/已收</th><th>ready µs</th><th>start µs</th><th>end µs</th><th>状态</th></tr></thead><tbody id="tasks"></tbody></table></div></div>
<div class="card"><h2>配置与证据</h2><p>原始证据与本 HTML 在同目录：experiment.json、traffic.csv、task_statistics.csv、port_statistics.csv、command-manifest.json、execution.json、stdout.log、summary.json。HTML 可单独下载到本机离线打开。</p><details><summary>完整实验配置</summary><pre id="config"></pre></details><pre id="errors"></pre></div>
<script id="data" type="application/json">__DATA__</script><script>
'use strict';const D=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id),S=D.summary;let page=0;
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const us=x=>+x<0?'—':(+x/1e6).toFixed(3);
$('name').textContent=D.spec.name;$('goal').textContent='目标：'+D.spec.goal;$('prediction').textContent='运行前预测：'+D.spec.prediction;
$('metrics').innerHTML=[['状态',S.status],['完成任务',S.completed+'/'+S.tasks],['总窗口 µs',S.makespan_us===null?'—':S.makespan_us.toFixed(3)],['重传帧',S.replay_frames],['本机运行秒数',S.wall_seconds]].map(([k,v])=>'<div class="metric">'+esc(k)+'<br><strong>'+esc(v)+'</strong></div>').join('');
$('semantics').textContent='依赖通知延迟：'+D.spec.runtime.visibility_ns+' ns（仿真调度抽象，不走网络，单线程与多线程保持相同）。任务/分片编号使用 PacketTag，仅作仿真元数据，不增加线上字节。每任务注入/重试间隔：'+D.spec.runtime.interval_ns+' ns；每端点每 VC 待发队列上限：'+D.spec.runtime.queue_bytes+' B。';
$('config').textContent=JSON.stringify(D.spec,null,2);$('errors').textContent=(S.errors||[]).join('\n');
for(const x of [...new Set(D.tasks.map(t=>t.src))].sort((a,b)=>a-b)){let o=document.createElement('option');o.value=x;o.textContent=x;$('source').append(o)}
for(const x of [...new Set(D.tasks.map(t=>t.label))]){let o=document.createElement('option');o.value=x;o.textContent=x;$('label').append(o)}
const stats=new Map(D.stats.map(x=>[+x.task_id,x]));
function draw(){let selected=D.tasks.filter(t=>($('source').value==='all'||t.src===+$('source').value)&&($('label').value==='all'||t.label===$('label').value));const pages=Math.max(1,Math.ceil(selected.length/80));page=Math.max(0,Math.min(page,pages-1));$('page').textContent=(page+1)+' / '+pages+' 页';let rows=selected.slice(page*80,page*80+80);let end=Math.max(1,...rows.flatMap(t=>{let r=stats.get(t.id);return r?[+r.end_ps,+r.start_ps]:[0]}));let svg='<text x="150" y="18">0 µs</text><text x="840" y="18">'+(end/1e6).toFixed(3)+' µs</text>';const scale=x=>150+750*Math.max(0,x)/end;
rows.forEach((t,i)=>{let r=stats.get(t.id),y=42+i*24;if(!r)return;let a=t.bytes===0?+r.ready_ps:+r.start_ps,b=+r.end_ps;svg+='<text x="4" y="'+(y+4)+'" font-size="12">#'+t.id+' '+t.src+'→'+t.dst+'</text><line x1="'+scale(a)+'" x2="'+scale(b<0?Math.max(a,0):b)+'" y1="'+y+'" y2="'+y+'" stroke="'+(b<0?'#b3261e':t.bytes===0?'#9467bd':'#126b83')+'" stroke-width="7" '+(t.bytes===0?'stroke-dasharray="5 3"':'')+'><title>'+esc(t.label)+' start='+us(r.start_ps)+' end='+us(r.end_ps)+' µs</title></line>';if(+r.last_enqueue_ps>=0)svg+='<circle cx="'+scale(+r.last_enqueue_ps)+'" cy="'+y+'" r="3" fill="#777"><title>最后分片入队 '+us(r.last_enqueue_ps)+' µs</title></circle>';});$('timeline').setAttribute('viewBox','0 0 960 '+Math.max(80,rows.length*24+50));$('timeline').innerHTML=svg;
$('tasks').innerHTML=rows.map(t=>{let r=stats.get(t.id);return '<tr>'+[t.id,t.label,t.src+'→'+t.dst,t.bytes+'/'+(r?r.received_bytes:0),r?us(r.ready_ps):'—',r?us(r.start_ps):'—',r?us(r.end_ps):'—',r?r.status:'missing'].map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>'}).join('');}
$('source').onchange=$('label').onchange=()=>{page=0;draw()};$('prev').onclick=()=>{page--;draw()};$('next').onclick=()=>{page++;draw()};draw();
let totals=Array.from({length:D.spec.topology.hosts},()=>[0,0]);D.tasks.forEach(t=>totals[t.src][0]+=t.bytes);D.stats.forEach(r=>totals[+r.dst][1]+=+r.received_bytes);let max=Math.max(1,...totals.flat()),bars='';totals.forEach(([a,b],i)=>{let y=i*30+24;bars+='<text x="0" y="'+(y+10)+'">'+i+'</text>';[[a,'#126b83'],[b,'#269777']].forEach(([v,c],j)=>bars+='<rect x="65" y="'+(y+j*11)+'" width="'+700*v/max+'" height="9" fill="'+c+'"><title>'+v/1024+' KiB</title></rect>');bars+='<text x="780" y="'+(y+12)+'" font-size="12">'+(a/1024).toFixed(1)+' / '+(b/1024).toFixed(1)+'</text>';});$('bytes').setAttribute('viewBox','0 0 960 '+(totals.length*30+40));$('bytes').innerHTML=bars;
$('ports').innerHTML=D.ports.map(p=>'<tr>'+[p.node+':'+p.port,p.replay_frames,p.replay_sessions,p.nack_tx,p.credit_exhausted,p.discard].map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('');
</script></html>'''
    (run/'report.html').write_text(template.replace('__DATA__',data))
    (run/'report.md').write_text('# SUE Scale-Up Ethernet 仿真平台 v2 实验结果\n\n'+spec['goal']+'\n\n```json\n'+json.dumps(summary,ensure_ascii=False,indent=2)+'\n```\n\n详细解释与交互图见 report.html。计算为固定等待，依赖通知不走网络；不代表真实模型推理吞吐。\n')
